            "builtinRecorder" -> Recorder.setBuiltinOn(c, v)
            "previewMini" -> Prefs.store(c).edit().putBoolean("ui_preview_mini", v).apply()
            "showItem.w_title" -> Prefs.setShowItem(c, "w_title", v)
            "showItem.w_count" -> Prefs.setShowItem(c, "w_count", v)
            "showItem.w_mic" -> Prefs.setShowItem(c, "w_mic", v)
