            "hideEmpty.title" -> Prefs.setHideWhenEmpty(c, "title", v)
            "hideEmpty.mic" -> Prefs.setHideWhenEmpty(c, "mic", v)
            "hideEmpty.note" -> Prefs.setHideWhenEmpty(c, "note", v)
            "hideEmpty.clear" -> Prefs.setHideWhenEmpty(c, "clear", v)
            "showPart.clock" -> Prefs.setShow(c, "clock", v)
            "showPart.weather" -> Prefs.setShow(c, "weather", v)
            "showPart.date" -> Prefs.setShow(c, "date", v)
            "showPart.maps" -> Prefs.setShow(c, "maps", v)
            "showPart.dial" -> Prefs.setShow(c, "dial", v)
            else -> {}
        }
    }

    fun getText(c: Context, id: String): String = when (id) {
        "emptyText" -> Prefs.emptyText(c)
        "updatedLabel" -> Prefs.updatedLabel(c)
        else -> ""
    }

    fun setText(c: Context, id: String, v: String) {
        when (id) {
            "emptyText" -> Prefs.setEmptyText(c, v)
            "updatedLabel" -> Prefs.setUpdatedLabel(c, v)
            else -> {}
        }
    }
}
